nums = [5, 3, 8, 1]
for i in range(len(nums)):
    # 在 i..末尾 里找最小
    mi = i
    for j in range(i + 1, len(nums)):
        if nums[j] < nums[mi]:
            mi = j
    nums[i], nums[mi] = nums[mi], nums[i]
    print(f'第{i+1}轮: {nums}')
print('最终:', nums)

def find(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        print(f'检查区间 [{lo}, {hi}] 中间下标 {mid} → {nums[mid]}')
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

print('结果:', find([1, 3, 5, 7, 9, 11], 7))

def make_change(amount):
    coins = [25, 10, 5, 1]
    used = []
    for c in coins:
        while amount >= c:
            amount -= c
            used.append(c)
    return used

print('61 分:', make_change(61))
print('件数:', len(make_change(61)))
